public class NavigationOrder {public string Group;public List<string> Routes=new List<string>();}
partial class TerminalWindow {
 static readonly string[][] NavigationGroups={new[]{"提醒与值班","侦探备忘录"},new[]{"文件与启动","文件搜索","快捷入口","证物卡","磁盘与电池"},new[]{"桌宠与声音","动作与移动","动作演示","气泡外观","原声配音","原声候选"},new[]{"效率工具","便签","文本","剪贴板","桌面工具","语音与快捷键"},new[]{"系统与通知","启动与窗口","性能监控","线索档案馆","监控与预警","任务栏外观","系统与网络"},new[]{"数据管理","数据与备份"}};
 readonly Dictionary<string,StackPanel> navigationGroups=new Dictionary<string,StackPanel>();
 readonly Dictionary<string,StackPanel> navigationItems=new Dictionary<string,StackPanel>();
 NavigationDrag activeNavigationDrag;StackPanel navigationHost;object navigationDragToken=new object();
 sealed class NavigationDrag {public object Token;public string Group,Route;public FrameworkElement View;}
 public static List<NavigationOrder> NormalizeNavigation(IEnumerable<NavigationOrder> saved){var input=(saved??new NavigationOrder[0]).Where(x=>x!=null).ToArray();var result=new List<NavigationOrder>();foreach(string name in input.Select(x=>x.Group).Concat(NavigationGroups.Select(x=>x[0])).Distinct()){var canonical=NavigationGroups.FirstOrDefault(x=>x[0]==name);if(canonical==null)continue;var old=input.FirstOrDefault(x=>x.Group==name);var routes=(old==null||old.Routes==null?new string[0]:old.Routes.ToArray()).Concat(canonical.Skip(1)).Where(x=>canonical.Skip(1).Contains(x)).Distinct().ToList();result.Add(new NavigationOrder{Group=name,Routes=routes});}return result;}
 void BuildSortableNavigation(StackPanel nav,ScrollViewer scroll){navigationHost=nav;AddNavigation(nav,"总览","tasks");foreach(var group in NormalizeNavigation(assistant.Config.Monitor.NavigationOrder)){
  var outer=new StackPanel{Tag=group.Group,Margin=new Thickness(0,12,0,0)};nav.Children.Add(outer);navigationGroups[group.Group]=outer;var title=new Grid{MinHeight=32};title.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(24)});title.ColumnDefinitions.Add(new ColumnDefinition());outer.Children.Add(title);var grip=NavigationGrip("拖动分组-"+group.Group);title.Children.Add(grip);var label=Text(group.Group,11);label.VerticalAlignment=VerticalAlignment.Center;Grid.SetColumn(label,1);title.Children.Add(label);WireNavigationDrag(grip,outer,group.Group,null,nav,scroll);
  var items=new StackPanel();navigationItems[group.Group]=items;
  if(group.Group=="效率工具"){
   utilityNav=new Expander{Content=items,IsExpanded=false};var template=new ControlTemplate(typeof(Expander));var stack=new FrameworkElementFactory(typeof(StackPanel));var toggle=new FrameworkElementFactory(typeof(ToggleButton));toggle.SetValue(ContentControl.ContentProperty,"实用工具箱  ·  5 项      ﹀");toggle.SetValue(Control.TemplateProperty,ToolsToggleTemplate());toggle.SetValue(Control.PaddingProperty,new Thickness(10,9,10,9));toggle.SetValue(Control.HorizontalContentAlignmentProperty,HorizontalAlignment.Left);toggle.SetValue(FrameworkElement.ToolTipProperty,"点击展开或收起效率工具；展开后可拖动排列功能");toggle.SetResourceReference(Control.BackgroundProperty,"DeskSelected");toggle.SetResourceReference(Control.ForegroundProperty,"DeskText");toggle.SetResourceReference(Control.BorderBrushProperty,"DeskLine");toggle.SetBinding(ToggleButton.IsCheckedProperty,new System.Windows.Data.Binding("IsExpanded"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent),Mode=System.Windows.Data.BindingMode.TwoWay});stack.AppendChild(toggle);var presenter=new FrameworkElementFactory(typeof(ContentPresenter),"ToolsContent");presenter.SetBinding(ContentPresenter.ContentProperty,new System.Windows.Data.Binding("Content"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)});presenter.SetValue(UIElement.VisibilityProperty,Visibility.Collapsed);stack.AppendChild(presenter);template.VisualTree=stack;var trigger=new Trigger{Property=Expander.IsExpandedProperty,Value=true};trigger.Setters.Add(new Setter(UIElement.VisibilityProperty,Visibility.Visible,"ToolsContent"));template.Triggers.Add(trigger);utilityNav.Template=template;outer.Children.Add(utilityNav);
  }else outer.Children.Add(items);
  foreach(string route in group.Routes){var row=AddNavigation(items,route,group.Group=="桌宠与声音"?"move":group.Group=="系统与通知"?"bell":"tasks");row.Margin=new Thickness(16,0,0,0);var handle=NavigationGrip("拖动功能-"+route);handle.HorizontalAlignment=HorizontalAlignment.Left;handle.Margin=new Thickness(-17,0,0,0);row.Children.Add(handle);WireNavigationDrag(handle,row,group.Group,route,items,scroll);}
 }
 var reset=Button(nav,"恢复默认目录",()=>ResetNavigationOrder());reset.FontSize=10;reset.Margin=new Thickness(4,16,4,0);reset.ToolTip="只恢复导航分组及功能顺序，不修改功能设置";
 }
 static ControlTemplate ToolsToggleTemplate(){var template=new ControlTemplate(typeof(ToggleButton));var border=new FrameworkElementFactory(typeof(Border),"Surface");border.SetValue(Border.CornerRadiusProperty,new CornerRadius(9));border.SetValue(Border.BorderThicknessProperty,new Thickness(1));border.SetValue(Border.PaddingProperty,new Thickness(10,10,8,10));border.SetResourceReference(Border.BackgroundProperty,"DeskSidebar");border.SetResourceReference(Border.BorderBrushProperty,"DeskLine");var content=new FrameworkElementFactory(typeof(ContentPresenter));content.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);content.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);border.AppendChild(content);template.VisualTree=border;var selected=new Trigger{Property=ToggleButton.IsCheckedProperty,Value=true};selected.Setters.Add(new Setter(ContentControl.ContentProperty,"实用工具箱  ·  5 项      ⌃"));selected.Setters.Add(new Setter(Border.BackgroundProperty,new DynamicResourceExtension("DeskSelected"),"Surface"));selected.Setters.Add(new Setter(Border.BorderBrushProperty,new DynamicResourceExtension("DeskAccent"),"Surface"));template.Triggers.Add(selected);var hover=new Trigger{Property=UIElement.IsMouseOverProperty,Value=true};hover.Setters.Add(new Setter(Border.BackgroundProperty,new DynamicResourceExtension("DeskSelected"),"Surface"));template.Triggers.Add(hover);return template;}
 TextBlock NavigationGrip(string name){var grip=new TextBlock{Text="⠿",FontSize=17,Width=21,VerticalAlignment=VerticalAlignment.Center,Cursor=Cursors.SizeNS,ToolTip="按住拖动上下排序；蓝色边线表示放置位置"};grip.SetResourceReference(TextBlock.ForegroundProperty,"DeskMuted");System.Windows.Automation.AutomationProperties.SetName(grip,name);return grip;}
 void WireNavigationDrag(FrameworkElement grip,FrameworkElement view,string group,string route,StackPanel host,ScrollViewer scroll){Point press=new Point();bool pressed=false;grip.PreviewMouseLeftButtonDown+=(s,e)=>{press=e.GetPosition(grip);pressed=true;grip.CaptureMouse();e.Handled=true;};grip.MouseLeftButtonUp+=(s,e)=>{pressed=false;grip.ReleaseMouseCapture();e.Handled=true;};grip.LostMouseCapture+=(s,e)=>pressed=false;grip.MouseMove+=(s,e)=>{if(!pressed||e.LeftButton!=MouseButtonState.Pressed)return;var p=e.GetPosition(grip);if(Math.Abs(p.Y-press.Y)<SystemParameters.MinimumVerticalDragDistance&&Math.Abs(p.X-press.X)<SystemParameters.MinimumHorizontalDragDistance)return;pressed=false;grip.ReleaseMouseCapture();var data=new NavigationDrag{Token=navigationDragToken,Group=group,Route=route,View=view};try{activeNavigationDrag=data;DragDrop.DoDragDrop(grip,new DataObject("Conan.NavigationOrder","local"),DragDropEffects.Move);}finally{activeNavigationDrag=null;ClearNavigationCue();}};
  view.AllowDrop=true;view.DragOver+=(s,e)=>{var drag=e.Data.GetDataPresent("Conan.NavigationOrder",false)?activeNavigationDrag:null;if(!ValidNavigationDrag(drag,group,route)){e.Effects=DragDropEffects.None;return;}ClearNavigationCue();bool after=e.GetPosition(view).Y>view.ActualHeight/2;NavigationCue(view,after);double y=e.GetPosition(scroll).Y;if(y<32)scroll.ScrollToVerticalOffset(scroll.VerticalOffset-12);else if(y>scroll.ActualHeight-32)scroll.ScrollToVerticalOffset(scroll.VerticalOffset+12);e.Effects=DragDropEffects.Move;e.Handled=true;};
  view.DragLeave+=(s,e)=>ClearNavigationCue();view.Drop+=(s,e)=>{var drag=e.Data.GetDataPresent("Conan.NavigationOrder",false)?activeNavigationDrag:null;if(!ValidNavigationDrag(drag,group,route))return;bool after=e.GetPosition(view).Y>view.ActualHeight/2;MoveNavigationView(host,drag.View,view,after);ClearNavigationCue();PersistNavigation();e.Handled=true;};
 }
 bool ValidNavigationDrag(NavigationDrag drag,string group,string route){return drag!=null&&Object.ReferenceEquals(drag.Token,navigationDragToken)&&((drag.Route==null&&route==null)||(drag.Route!=null&&route!=null&&drag.Group==group));}
 System.Windows.Documents.Adorner navigationAdorner;
 void NavigationCue(FrameworkElement view,bool after){var layer=System.Windows.Documents.AdornerLayer.GetAdornerLayer(view);if(layer==null)return;navigationAdorner=new NavigationInsertion(view,after);layer.Add(navigationAdorner);}
 void ClearNavigationCue(){if(navigationAdorner!=null){var layer=System.Windows.Documents.AdornerLayer.GetAdornerLayer(navigationAdorner.AdornedElement);if(layer!=null)layer.Remove(navigationAdorner);navigationAdorner=null;}}
 public static void MoveNavigationView(StackPanel host,FrameworkElement source,FrameworkElement target,bool after){if(source==target||source.Parent!=host||target.Parent!=host)return;host.Children.Remove(source);host.Children.Insert(host.Children.IndexOf(target)+(after?1:0),source);}
 void ResetNavigationOrder(){SaveMonitor(()=>assistant.Config.Monitor.NavigationOrder=new List<NavigationOrder>());navigation.Clear();navigationGroups.Clear();navigationItems.Clear();var scroll=(ScrollViewer)navigationHost.Parent;navigationHost.Children.Clear();BuildSortableNavigation(navigationHost,scroll);TerminalAppearance.BindTree(navigationHost);}
 void PersistNavigation(){var values=navigationHost.Children.OfType<StackPanel>().Where(x=>x.Tag is string&&navigationItems.ContainsKey((string)x.Tag)).Select(x=>new NavigationOrder{Group=(string)x.Tag,Routes=navigationItems[(string)x.Tag].Children.OfType<Grid>().Select(r=>navigation.First(p=>Object.ReferenceEquals(p.Value.Parent,r)).Key).ToList()}).ToList();SaveMonitor(()=>assistant.Config.Monitor.NavigationOrder=values);}
 sealed class NavigationInsertion:System.Windows.Documents.Adorner {readonly bool after;public NavigationInsertion(UIElement element,bool bottom):base(element){after=bottom;IsHitTestVisible=false;}protected override void OnRender(DrawingContext dc){double y=after?AdornedElement.RenderSize.Height:0;var brush=(Brush)TryFindResource("DeskAccent")??Brushes.DodgerBlue;dc.DrawLine(new Pen(brush,3),new Point(0,y),new Point(AdornedElement.RenderSize.Width,y));dc.DrawEllipse(brush,null,new Point(2,y),3,3);}}
